// lib/python/bytes.mjs
//
// A `bytes`-like value is modelled as a plain JavaScript array of integers in
// the range 0..255.  These helpers cover the handful of `bytes` operations the
// program needs.

/** Number of leading occurrences of `byteValue`. */
export function countLeading(bytes, byteValue) {
  let n = 0;
  while (n < bytes.length && bytes[n] === byteValue) n += 1;
  return n;
}

/** Equivalent of `bytes.lstrip(single_byte)`. */
export function lstripByte(bytes, byteValue) {
  return bytes.slice(countLeading(bytes, byteValue));
}

/** `bytes([value] * count)`. */
export function repeatByte(byteValue, count) {
  const out = [];
  for (let i = 0; i < count; i += 1) out.push(byteValue);
  return out;
}

/** Concatenation of any number of byte arrays. */
export function concatBytes(...parts) {
  const out = [];
  for (const part of parts) {
    for (const value of part) out.push(value);
  }
  return out;
}

/** Byte values of an ASCII-only JavaScript string. */
export function bytesFromAscii(text) {
  const out = [];
  for (let i = 0; i < text.length; i += 1) out.push(text.charCodeAt(i));
  return out;
}

/** Interpret ASCII byte values as a JavaScript string. */
export function asciiFromBytes(bytes) {
  let out = '';
  for (const value of bytes) out += String.fromCharCode(value);
  return out;
}

// lib/base58/codec.mjs
//
// `b58encode` / `b58decode`, reproduced from the observable behaviour of the
// `base58` package.
//
// Notes established by probing the reference program:
//   * decode rstrips *trailing* Unicode whitespace from the input string before
//     anything else (leading whitespace is therefore an error),
//   * the string is then encoded as strict ASCII — non-ASCII input raises
//     UnicodeEncodeError, not ValueError,
//   * leading '1' characters map to leading 0x00 bytes and vice versa.
//
// Failures carry the same Python frame stack the packaged library shows, so the
// traceback printed on stderr keeps its original shape.

import { PythonError } from '../python/errors.mjs';
import { concatBytes, countLeading, repeatByte } from '../python/bytes.mjs';
import { encodeAscii, rstrip } from '../python/unicode.mjs';
import { bytesToInt, intToBytes } from '../numeric/bigint.mjs';
import { ZERO_CHAR_BYTE } from './alphabet.mjs';
import { b58decodeInt, b58encodeInt } from './int.mjs';

const MODULE = 'base58/__init__.py';

/** Attach the library frames that CPython would have unwound through. */
function withFrames(error, innerName, innerLine, callerLine) {
  if (error instanceof PythonError) {
    error.unshiftFrame({ file: MODULE, line: innerLine, name: innerName });
    error.unshiftFrame({ file: MODULE, line: callerLine, name: 'b58decode' });
  }
  return error;
}

/**
 * `base58.b58encode(v)` where `v` is a byte array.
 *
 * @param {number[]} bytes
 * @returns {number[]} the encoded value, as ASCII bytes (a Python `bytes`)
 */
export function b58encode(bytes) {
  const originalLength = bytes.length;
  const leadingZeros = countLeading(bytes, 0x00);
  const stripped = bytes.slice(leadingZeros);

  const encoded = b58encodeInt(bytesToInt(stripped), { defaultOne: false });

  const out = repeatByte(ZERO_CHAR_BYTE, originalLength - stripped.length);
  for (let i = 0; i < encoded.length; i += 1) out.push(encoded.charCodeAt(i));
  return out;
}

/**
 * `base58.b58decode(v)` where `v` is a string.
 *
 * @param {string} text
 * @returns {number[]} the decoded value (a Python `bytes`)
 */
export function b58decode(text) {
  // b58decode: `if b' ' not in alphabet: v = v.rstrip()`
  const trimmed = rstrip(text);

  let bytes;
  try {
    bytes = encodeAscii(trimmed); // scrub_input
  } catch (error) {
    throw withFrames(error, 'scrub_input', 30, 118);
  }

  const originalLength = bytes.length;
  const stripped = bytes.slice(countLeading(bytes, ZERO_CHAR_BYTE));

  let acc;
  try {
    acc = b58decodeInt(stripped);
  } catch (error) {
    throw withFrames(error, 'b58decode_int', 104, 124);
  }

  return concatBytes(
    repeatByte(0x00, originalLength - stripped.length),
    intToBytes(acc),
  );
}
