// Independent base58 encoder (bitcoin alphabet), mirroring the python `base58`
// package semantics: leading 0x00 bytes -> leading '1', remainder as bignum.
const AB = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';

export function b58encodeBytes(bytes) {
  let lead = 0;
  while (lead < bytes.length && bytes[lead] === 0) lead++;
  const rest = bytes.slice(lead);
  let acc = 0n;
  for (const b of rest) acc = acc * 256n + BigInt(b);
  let s = '';
  while (acc > 0n) { const d = acc % 58n; s = AB[Number(d)] + s; acc = acc / 58n; }
  return AB[0].repeat(lead) + s;
}

// Sanity: round-trip check against a straightforward decoder.
export function b58decodeBytes(text) {
  let lead = 0;
  while (lead < text.length && text[lead] === AB[0]) lead++;
  const rest = text.slice(lead);
  let acc = 0n;
  for (const ch of rest) {
    const i = AB.indexOf(ch);
    if (i < 0) throw new Error('bad char ' + JSON.stringify(ch));
    acc = acc * 58n + BigInt(i);
  }
  const out = [];
  while (acc > 0n) { out.push(Number(acc % 256n)); acc = acc / 256n; }
  out.reverse();
  return new Array(lead).fill(0).concat(out);
}
