  return new Promise((res) => {
    execFile(cmd, args, { encoding: 'utf8', maxBuffer: 1 << 28 }, (err, so, se) => {
      res({ out: so ?? '', err: se ?? '', code: err ? (err.code ?? 0) : 0 });
    });
  });
}

async function compare(argv) {
  const [a, b] = await Promise.all([run(EXE, argv), run(process.execPath, [PORT, ...argv])]);
