// lib/python/unicode.mjs
//
// Code-point level string helpers that reproduce the pieces of CPython's `str`
// behaviour this program depends on: `str.rstrip()`, `str.encode('ascii')` and
// `str.encode('utf-8')`.
//
// Byte sequences are represented as plain JavaScript arrays of integers in
// 0..255 — see lib/python/bytes.mjs.

import { PyUnicodeEncodeError } from './errors.mjs';

/**
 * Code points for which CPython's `str.isspace()` is true.  Established
 * empirically against the reference program (U+001B, U+180E, U+200B, U+2060 and
 * U+FEFF are deliberately absent — Python does not treat them as whitespace).
 */
const WHITESPACE = new Set([
  0x09, 0x0a, 0x0b, 0x0c, 0x0d,
  0x1c, 0x1d, 0x1e, 0x1f,
  0x20,
  0x85,
  0xa0,
  0x1680,
  0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005,
  0x2006, 0x2007, 0x2008, 0x2009, 0x200a,
  0x2028, 0x2029,
  0x202f,
  0x205f,
  0x3000,
]);

export function isPythonSpace(codePoint) {
  return WHITESPACE.has(codePoint);
}

/** Split a string into its code points (surrogate pairs kept together). */
export function toCodePoints(text) {
  const points = [];
  for (const ch of text) points.push(ch.codePointAt(0));
  return points;
}

/** Equivalent of Python's `str.rstrip()` (no argument: strip all whitespace). */
export function rstrip(text) {
  const points = toCodePoints(text);
  let end = points.length;
  while (end > 0 && isPythonSpace(points[end - 1])) end -= 1;
  return points.slice(0, end).map((cp) => String.fromCodePoint(cp)).join('');
}

/** Lowercase, zero-padded hex without a `0x` prefix. */
function hex(value, width) {
  let out = value.toString(16);
  while (out.length < width) out = `0${out}`;
  return out;
}

/**
 * How CPython renders the offending code point inside a UnicodeEncodeError
 * message.  Note this is *not* repr(): printable non-ASCII characters are still
 * shown as escapes.
 */
export function unicodeErrorCharEscape(codePoint) {
  if (codePoint <= 0xff) return `\\x${hex(codePoint, 2)}`;
  if (codePoint <= 0xffff) return `\\u${hex(codePoint, 4)}`;
  return `\\U${hex(codePoint, 8)}`;
}

/**
 * Equivalent of Python's `str.encode('ascii')` with the default strict error
 * handler, including the exact UnicodeEncodeError message.  Positions are
 * reported as code-point indices, and a run of consecutive non-encodable code
 * points is reported as a range.
 *
 * @param {string} text
 * @returns {number[]} the ASCII bytes
 */
export function encodeAscii(text) {
  const points = toCodePoints(text);
  const bytes = [];
  for (let i = 0; i < points.length; i += 1) {
    const cp = points[i];
    if (cp < 0x80) {
      bytes.push(cp);
      continue;
    }
    // Find the extent of the non-encodable run, as CPython's error handler does.
    let end = i;
    while (end + 1 < points.length && points[end + 1] >= 0x80) end += 1;
    const tail = 'ordinal not in range(128)';
    const message = end === i
      ? `'ascii' codec can't encode character '${unicodeErrorCharEscape(cp)}' `
        + `in position ${i}: ${tail}`
      : `'ascii' codec can't encode characters in position ${i}-${end}: ${tail}`;
    throw new PyUnicodeEncodeError(message);
  }
  return bytes;
}

/**
 * Equivalent of Python's `str.encode()` (UTF-8).  Surrogate pairs are combined;
 * a stray surrogate — unreachable through `process.argv`, which is already
 * sanitised by the runtime — is encoded as U+FFFD.
 *
 * @param {string} text
 * @returns {number[]} the UTF-8 bytes
 */
export function encodeUtf8(text) {
  const bytes = [];
  for (const cp of toCodePoints(text)) {
    const point = cp >= 0xd800 && cp <= 0xdfff ? 0xfffd : cp;
    if (point < 0x80) {
      bytes.push(point);
    } else if (point < 0x800) {
      bytes.push(0xc0 | (point >> 6), 0x80 | (point & 0x3f));
    } else if (point < 0x10000) {
      bytes.push(
        0xe0 | (point >> 12),
        0x80 | ((point >> 6) & 0x3f),
        0x80 | (point & 0x3f),
      );
    } else {
      bytes.push(
        0xf0 | (point >> 18),
        0x80 | ((point >> 12) & 0x3f),
        0x80 | ((point >> 6) & 0x3f),
        0x80 | (point & 0x3f),
      );
    }
  }
  return bytes;
}
